css:
[data-testid="sidebar-row-card"] > div {
  height: auto !important;
  padding-block: 6px !important;
  display: grid !important;
  grid-template-columns: minmax(0, 1fr) auto;
  column-gap: 8px;
  row-gap: 2px;
  align-items: center;
}
[data-testid="sidebar-row-card"] > div > :nth-child(1) { grid-column: 1 / -1; }
[data-testid="sidebar-row-card"] > div > :nth-child(2) { grid-column: 1; grid-row: 2; margin-top: 0 !important; }
[data-testid="sidebar-row-card"] > div > :nth-child(2):last-child { grid-column: 1 / -1; }
[data-testid="sidebar-row-card"] > div > :nth-child(3) { grid-column: 2; grid-row: 2; margin-top: 0 !important; }
[data-testid="sidebar-row-card"] > div > :nth-child(3) > svg:first-child,
[data-testid="sidebar-row-card"] > div > :nth-child(3) > svg:first-child + span { display: none !important; }
/* Hover or keyboard focus: show the device next to the badges */
[data-testid="sidebar-row-card"]:is(:hover, :focus-visible) > div > :nth-child(3) > svg:first-child { display: block !important; }
[data-testid="sidebar-row-card"]:is(:hover, :focus-visible) > div > :nth-child(3) > svg:first-child + span {
  display: block !important;
  flex: 0 1 auto !important;
  max-width: 10rem;
}
/* Hide project icons on thread rows (cards and one-line rows) */
[data-testid="sidebar-row-card"] > div > :nth-child(1) > .size-4 { display: none !important; }
[data-testid="sidebar-row-slim"] span:has(> .size-4:only-child) { display: none !important; }
